var sb=new System.Text.StringBuilder();var mesh=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>("Assets/Poolcore/Meshes/Hall Entry Slope.asset");
var so=new UnityEditor.SerializedObject(mesh);var p=so.GetIterator();while(p.NextVisible(true)){if(p.propertyPath.ToLower().Contains("colli")||p.propertyPath.ToLower().Contains("cook")||p.propertyPath.ToLower().Contains("bake"))sb.AppendLine(p.propertyPath+" "+p.propertyType+" "+(p.propertyType==UnityEditor.SerializedPropertyType.Integer?p.intValue.ToString():""));}
foreach(var m in typeof(UnityEditor.MeshUtility).GetMethods(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static))if(m.Name.ToLower().Contains("colli")||m.Name.ToLower().Contains("bake"))sb.AppendLine(m.ToString());return sb.ToString();
